package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.nio.file.Path;

import org.eclipse.rdf4j.common.transaction.IsolationLevels;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.SailConnection;
import org.eclipse.rdf4j.sail.lmdb.config.FrontierEstimatorMode;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.eclipse.rdf4j.sail.lmdb.sketch.SketchBasedJoinEstimator;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class LmdbEstimatorShutdownTest {

	@Test
	void dirtyStoppedSynopsisDoesNotRebuildAfterStoreAdmissionCloses(@TempDir Path directory) {
		InspectableStore store = new InspectableStore(directory, new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.OFF)
				.setSketchEstimatorEnabled(true)
				.setSketchEstimatorMemoryBudgetBytes(4L * 1024L * 1024L));
		store.setExperimentalQueryOptimizations(true);
		store.init();
		assertSketchFixtureProfile(store);
		try {
			SketchBasedJoinEstimator estimator = store.getBackingStore().getSketchBasedJoinEstimator();
			estimator.stop();
			SimpleValueFactory vf = SimpleValueFactory.getInstance();
			try (SailConnection connection = store.getConnection()) {
				connection.begin(IsolationLevels.SNAPSHOT);
				connection.addStatement(vf.createIRI("urn:shutdown:subject"), vf.createIRI("urn:shutdown:predicate"),
						vf.createLiteral("committed"));
				connection.commit();
			}
			estimator.discardAndMarkForRebuild();
			assertFalse(estimator.isReadyNonBlocking(), "the synopsis must still need a rebuild at shutdown");
			assertDoesNotThrow(store::shutDown);
			assertFalse(store.initialized());
		} finally {
			if (store.initialized()) {
				store.shutDown();
			}
		}
	}

	private static final class InspectableStore extends LmdbStore {
		private InspectableStore(Path directory, LmdbStoreConfig config) {
			super(directory.toFile(), config);
		}

		private boolean initialized() {
			return isInitialized();
		}
	}

	private static void assertSketchFixtureProfile(LmdbStore store) {
		try {
			assertTrue(store.getQueryExecutionPolicy().experimentalQueryOptimizations());
			assertNotNull(store.getBackingStore().getSketchBasedJoinEstimator());
		} catch (AssertionError failure) {
			try {
				store.shutDown();
			} catch (RuntimeException | Error closeFailure) {
				failure.addSuppressed(closeFailure);
			}
			throw failure;
		}
	}
}
